/**
 * BooKi - "Command Center" theme switcher.
 *
 * Repaints Bootstrap's runtime CSS custom properties (--bs-primary and the
 * handful of sibling tokens that are NOT derived from it at runtime - see
 * comment on FAMILIES below) so a theme/custom palette applies instantly,
 * without a page reload and without touching any server-rendered view.
 *
 * Choice is a per-browser preference (localStorage), not a tenant setting -
 * this intentionally avoids a settings-table/migration change so it stays
 * a zero-risk, purely additive layer on top of the real backend.
 */
(function () {
    'use strict';

    var STORAGE_KEY = 'ki_command_center_theme';

    var FAMILIES = [
        {
            fam: 'Varsayılan (Ki Teal)',
            items: [{ key: 'teal', label: 'Ki Teal', brand: '#329b86', dark: '#257765' }],
        },
        {
            fam: 'Bordo',
            items: [
                { key: 'bordo-1', label: 'Bordo Klasik', brand: '#93303c', dark: '#6e232c' },
                { key: 'bordo-2', label: 'Bordo Koyu', brand: '#611b23', dark: '#3f1218' },
                { key: 'bordo-3', label: 'Bordo Açık', brand: '#b8495a', dark: '#93303c' },
            ],
        },
        {
            fam: 'Sarı',
            items: [
                { key: 'sari-1', label: 'Sarı Klasik', brand: '#b3811e', dark: '#8a6216' },
                { key: 'sari-2', label: 'Sarı Koyu', brand: '#8a6216', dark: '#614510' },
                { key: 'sari-3', label: 'Sarı Açık', brand: '#cc9a35', dark: '#a67c1e' },
            ],
        },
        {
            fam: 'Koyu Yeşil',
            items: [
                { key: 'yesil-1', label: 'Yeşil Klasik', brand: '#1f6b46', dark: '#154a31' },
                { key: 'yesil-2', label: 'Yeşil Koyu', brand: '#154a31', dark: '#0d3220' },
                { key: 'yesil-3', label: 'Yeşil Açık', brand: '#2c8a5c', dark: '#1f6b46' },
            ],
        },
        {
            fam: 'Mavi',
            items: [
                { key: 'mavi-1', label: 'Mavi Klasik', brand: '#2c5c8a', dark: '#1f4266' },
                { key: 'mavi-2', label: 'Mavi Koyu', brand: '#1f4266', dark: '#142c46' },
                { key: 'mavi-3', label: 'Mavi Açık', brand: '#3d76ad', dark: '#2c5c8a' },
            ],
        },
    ];

    function hexToRgb(hex) {
        var m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!m) return [50, 155, 134];
        return [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)];
    }

    function mix(hex, target, amount) {
        var c = hexToRgb(hex);
        var t = hexToRgb(target);
        var r = Math.round(c[0] + (t[0] - c[0]) * amount);
        var g = Math.round(c[1] + (t[1] - c[1]) * amount);
        var b = Math.round(c[2] + (t[2] - c[2]) * amount);
        return 'rgb(' + r + ', ' + g + ', ' + b + ')';
    }

    function darken(hex, amount) { return mix(hex, '#000000', amount); }
    function lighten(hex, amount) { return mix(hex, '#ffffff', amount); }

    function styleTag() {
        var el = document.getElementById('ki-theme-dynamic');
        if (!el) {
            el = document.createElement('style');
            el.id = 'ki-theme-dynamic';
            document.head.appendChild(el);
        }
        return el;
    }

    function apply(brand, dark, accent, key, persist) {
        var rgb = hexToRgb(brand).join(', ');
        var hoverBg = dark;
        var hoverBorder = darken(dark, 0.08);
        var activeBg = darken(dark, 0.12);
        var activeBorder = darken(dark, 0.18);

        var css = ':root{' +
            '--bs-primary:' + brand + ';' +
            '--bs-primary-rgb:' + rgb + ';' +
            '--bs-primary-text-emphasis:' + darken(brand, 0.55) + ';' +
            '--bs-primary-bg-subtle:' + lighten(brand, 0.88) + ';' +
            '--bs-primary-border-subtle:' + lighten(brand, 0.65) + ';' +
            (accent ? '--bs-info:' + accent + ';--bs-info-rgb:' + hexToRgb(accent).join(', ') + ';' : '') +
            '}' +
            '.btn-primary{' +
            '--bs-btn-color:#fff;' +
            '--bs-btn-bg:' + brand + ';' +
            '--bs-btn-border-color:' + brand + ';' +
            '--bs-btn-hover-color:#fff;' +
            '--bs-btn-hover-bg:' + hoverBg + ';' +
            '--bs-btn-hover-border-color:' + hoverBorder + ';' +
            '--bs-btn-active-color:#fff;' +
            '--bs-btn-active-bg:' + activeBg + ';' +
            '--bs-btn-active-border-color:' + activeBorder + ';' +
            '--bs-btn-disabled-color:#fff;' +
            '--bs-btn-disabled-bg:' + brand + ';' +
            '--bs-btn-disabled-border-color:' + brand + ';' +
            '--bs-btn-focus-shadow-rgb:' + rgb + ';' +
            '}';
        // BooKi (2026-09-11 redesign) - the sidebar is now a light surface (see
        // ki-command-center.min.css) with the brand color reserved for the active nav item, which
        // already repaints itself purely from the --bs-primary custom property above - no separate
        // solid-fill override needed here any more (that used to paint the whole sidebar the brand
        // color, which no longer matches the light-sidebar design).

        styleTag().textContent = css;

        if (persist !== false) {
            try {
                localStorage.setItem(STORAGE_KEY, JSON.stringify({ brand: brand, dark: dark, accent: accent || null, key: key || 'custom' }));
            } catch (e) { /* private mode / storage disabled - theme just won't persist */ }
        }
    }

    function restore() {
        var saved = null;
        try {
            saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
        } catch (e) { /* ignore corrupt value */ }
        if (saved && saved.brand && saved.dark) {
            apply(saved.brand, saved.dark, saved.accent, saved.key, false);
            return saved.key || 'custom';
        }
        return 'teal';
    }

    function swatchGrid(activeKey) {
        var html = '';
        FAMILIES.forEach(function (f) {
            html += '<div class="kcc-fam-label">' + f.fam + '</div><div class="kcc-swatch-row">';
            f.items.forEach(function (t) {
                var active = activeKey === t.key ? ' active' : '';
                html += '<button type="button" class="kcc-swatch' + active + '" title="' + t.label + '" ' +
                    'style="background:linear-gradient(135deg,' + t.brand + ' 55%,' + t.dark + ' 55%)" ' +
                    'data-key="' + t.key + '" data-brand="' + t.brand + '" data-dark="' + t.dark + '"></button>';
            });
            html += '</div>';
        });
        html += '<div class="kcc-fam-label">Özel Palet</div>' +
            '<div class="kcc-custom-pal">' +
            '<div class="kcc-color-field"><input type="color" id="kcc-c1" value="#329b86"><label>Ana Renk</label></div>' +
            '<div class="kcc-color-field"><input type="color" id="kcc-c2" value="#257765"><label>Koyu Ton</label></div>' +
            '<div class="kcc-color-field"><input type="color" id="kcc-c3" value="#4c78b8"><label>Vurgu</label></div>' +
            '<button type="button" class="btn btn-primary btn-sm ms-auto" id="kcc-apply-custom">Uygula</button>' +
            '</div>';
        return html;
    }

    function buildModal() {
        var existing = document.getElementById('kccThemeModal');
        if (existing) return existing;

        var saved = null;
        try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'); } catch (e) { /* ignore */ }
        var activeKey = saved && saved.key ? saved.key : 'teal';

        var wrap = document.createElement('div');
        wrap.innerHTML =
            '<div class="modal fade kcc-theme-modal" id="kccThemeModal" tabindex="-1" aria-hidden="true">' +
            '  <div class="modal-dialog modal-dialog-centered">' +
            '    <div class="modal-content">' +
            '      <div class="modal-header">' +
            '        <h5 class="modal-title">Renk Teması</h5>' +
            '        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Kapat"></button>' +
            '      </div>' +
            '      <div class="modal-body">' +
            '        <p class="text-muted small mb-2">Bir tema seçin veya kendi paletinizi oluşturun. Seçim bu tarayıcıda saklanır.</p>' +
            swatchGrid(activeKey) +
            '      </div>' +
            '    </div>' +
            '  </div>' +
            '</div>';
        var modalEl = wrap.firstElementChild;
        document.body.appendChild(modalEl);

        modalEl.querySelectorAll('.kcc-swatch[data-key]').forEach(function (btn) {
            btn.addEventListener('click', function () {
                apply(btn.dataset.brand, btn.dataset.dark, null, btn.dataset.key);
                modalEl.querySelectorAll('.kcc-swatch').forEach(function (s) { s.classList.remove('active'); });
                btn.classList.add('active');
                if (window.showMessage) {
                    window.showMessage('Tema uygulandı: ' + btn.title, 'success');
                }
            });
        });

        modalEl.querySelector('#kcc-apply-custom').addEventListener('click', function () {
            var c1 = modalEl.querySelector('#kcc-c1').value;
            var c2 = modalEl.querySelector('#kcc-c2').value;
            var c3 = modalEl.querySelector('#kcc-c3').value;
            apply(c1, c2, c3, 'custom');
            if (window.showMessage) {
                window.showMessage('Özel palet uygulandı', 'success');
            }
        });

        return modalEl;
    }

    function openPicker() {
        var modalEl = buildModal();
        if (window.bootstrap && window.bootstrap.Modal) {
            window.bootstrap.Modal.getOrCreateInstance(modalEl).show();
        } else {
            modalEl.style.display = 'block';
        }
    }

    window.KiTheme = { apply: apply, openPicker: openPicker };

    document.addEventListener('DOMContentLoaded', function () {
        restore();
        document.querySelectorAll('.kcc-theme-trigger').forEach(function (el) {
            el.addEventListener('click', function (e) {
                e.preventDefault();
                openPicker();
            });
        });
    });
})();
